with unpacked as (select id, effective_from, tier_prices, discounts, slice(tier_limits, 1, 2) as first_two_limits, aggregate(tier_prices, cast(0 as double), (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices from price_tiers where effective_from <= '2023-05-01') select date_trunc('quarter', effective_from) as quarter_start, approx_percentile(avg_tier_price, 0.5) as avg_tier_price_p50, count(*) as row_count from unpacked group by date_trunc('quarter', effective_from) having avg_tier_price_p50 >= 0 order by avg_tier_price_p50 desc
